--

INSERT INTO `halloffametbl` VALUES ('2014',1,'LauraHallofFamePicture1.png','LauraPeanutWinningAvatar.png','Laura Cutler <br> Peanuts <br> 2014 Winner','As both Grandmother and Mother, Laura took everyone by suprise and showed us \'experts\' how to walk the walk. Way to go Mom, Grandma and Laura!'),('2015',1,'SabrinaHallofFamePicture2015-1.png','SabrinaToothfairyWinningAvatar.png','Sabrina Hunzelman <br> Toothfairy <br> 2015 Winner','New to our group in 2015, Sabrina dominted first place. This soft spoken dental hygentist set her \'teeth\' into her analysis and took the \'crown\' with ease! Way to go Sabrina!'),('2016',1,'Sabrina2ndWinC.png','SabrinaToothfairyWinningAvatar.png','Sabrina Hunzelman <br> Toothfairy <br> 2016 Winner','Sabrina is our first repeat winner! The bar is now officially raised for the rest of us. Way to go Sabrina!'),('2017',1,'PaulaBishopHallofFamePic.png','PaulaHowkeyeWinningAvatar.png','Paula Bishop <br> Hawk Eye <br> 2017 Winner','Paula is a second year member. An avid tennis player, Paula clearly knows her sports. Way to go Paula!'),('2018',1,'donomalleyhof-2018.png','Don4HorsemanWinningAvatar.png','Don O\'Malley <br> 4Horsemen <br> 2018 Winner','Don is our first male winner! Long live the new King! Way to go Don!'),('2019',1,'TanyaTonyHallofFamePicture2.png','RemingtonHallofFamePicture1.png','Tanya Gorman, Tony Bruehl  and Remington <br> Team Remington <br> 2019 Winners','Tanya and Tony from Team Remington (their dog is Remington) put in a stellar season culminating in a spectacular win! Way to go Team Remington!'),('2020',1,'Chuck2026WinningPicture.png','ChuckAlaskanFishWinningAvatar.png','Chuck Miemiec <br> Alaskan Fisherman <br> 2020 Co-Winner','Chuck Miemiec (2015) long time member and fisherman extraordinaire! Way to go Chuck!!'),('2020',2,'SandyRudmanHallofFame.png','SandyRMaineWinningAvatar.png','Sandy Rudman <br> SandyR <br> 2020 Co-Winner','Sandy (2017) is one of our esteemed Maine-iacs! Way to go Sandy!!'),('2020',3,'BonnieHallofFamePicture2.png','BonnieSkinnyWinningAvatar.png','Bonnie Shuris <br> Skinny <br> 2020  Co-Winner','Bonnie (2014) is one of our original eight players! Way to go Bonnie!'),('2021',1,'OscarNewHallofFamePic2026.png','OscarGuzmanAvatar2A.png','Oscar Guzman <br> Hygenius <br> 2021 Winner','Oscar Guzman was in the hunt all year. Another Dental Hygentist (like his wife Toothfairy), Oscar kept his head clear and took the \'crown\' when it mattered! Way to go Oscar!'),('2022',1,'JefferyHallofFamePic3.png','JeffRoberts.png','Jeff Roberts <br> Daffy Duck  <br> 2022 Winner','Jeff Roberts did a great job picking this season. In the end it came down to the last game. Like a true Super Hero he picked wisely! Way to go Jeff!'),('2023',1,'DandMBradyHallofFamePics.png','SummervilleAvatarHallFame.png','Dan and Marilyn Brady <br> Sville 5  <br> 2023 Winner','Dan and Marilyn did something no one has done! They led most of the last third of the Season. That takes a keen mind with a balance of luck!  Way to go Dan and Marilyn!'),('2024',1,'ChrisHallofFamePick4.png','ChrisBurginHalloffame.png','Chris Burgin <br> The Juice is Loose <br> 2024 Winner','Chris has shown us how to start out winning, and to keep it going. He weathered all the permutations of a crazy NFL season!  As a skilled golfer he knows what it takes to stay on the fairway!   Way to go Chris!'),('2025',1,'bobbycraighalloffame.png','bobbycraig.png','Bobby Craig <br> Scotsman357 <br> 2025 Winner','Well done Bobby! You have been with us for 10 years. You have always been in the game. But this year you busted through! Persistence has its rewards! Congratulations! You da Man!'),('9999',1,'HallofFamePicture2.png','HallofFameAngryDonald.png','This could be you! ','Glowing praise and admiration for you!');

