INSERT INTO `membertbl` VALUES (1,'Tarrant Cutler',1,'AirDreamer','Male',0,'tarryc-desert-airstream.png','admin','tarrant.cutler@gmail.com',1,'68 Barley Neck Rd','Orleans','MA','02653',1,'9784734868',1,4,0,'Tammy and I started this group contest with an excel spreadsheet and 6 people. We had so much fun we decided to turn it into a website! Every year has been better than the year before!','1','tarryc','4038767355a9ebfcbc44611.97084065','active','2025-09-11 20:57:53',NULL),(2,'Tammy Jamieson Cutler',1,'Wildcat Wonder','Female',1,'tammy.png','admin','TJCutler@TandTWanderers.com',1,'Barley Neck Road','Orleans','MA','02653',1,'978-239-2650',1,4,0,'LOVE Football !!!  So Gald you have all joined this site to enjoy & share the sport with Good Family & Friends.  Game On !!!  Just make sure we ALL stand for OUR country\'s National Anthem!!','1','Wonder Wildcat',NULL,'active','2022-11-30 14:20:16',NULL),(6,'Laura Cutler',1,'Peanuts','Female',1,'LauraCutler.png','member','',0,'','Manchester by the Sea','MA','01944',1,'',0,4,1,'','1','peanuts',NULL,'inactive','2025-02-24 15:06:09',NULL),(7,'William Cutler',1,'DubCut','Male',1,'willavatar2019.png','member','',0,'','Hingham','MA','',1,'',0,4,1,'','1','DubCut',NULL,'inactive','2025-02-24 13:13:40',NULL),(8,'Bill Shuris',1,'Kiver','Male',1,'kiver.png','member','',0,'','Clinton','MA','01510',1,'',0,0,0,'','1','Kiver',NULL,'inactive','2025-02-24 13:29:09',NULL),(9,'Bonnie Shuris',1,'Skinny','Female',1,'bonnie.png','member','',0,'','Clinton','MA','01510',1,'',0,4,0,'I am a die hard Pats fan and always will be (at least as long as Tommy is playing)!','1','Skinny',NULL,'inactive','2025-02-24 13:27:58',NULL),(10,'Sandy Friedman',1,'SandyLand','Female',1,'sandyavatar.png','member','Sandyfriedman@comcast.net',0,'4938 NW 23rd Court','Boca Raton','FL','33431',1,'561-409-9388',0,0,0,'','1','gonefun',NULL,'active','2026-10-12 21:14:12',NULL),(11,'Lori Archuleta',1,'Tight End','Female',1,'lori.png','member','',0,'','Essex','MA','',1,'',0,4,1,'','1','Tight End',NULL,'inactive','2025-02-24 13:15:42',NULL),(12,'David Archuleta',1,'Archie','Male',1,'davida.png','member','davidarchuleta58@gmail.com',0,'35 Adams Road','Boxford','MA','01921',1,'603-408-1543',0,0,0,'','1','Archie',NULL,'inactive','2025-09-25 20:53:54',NULL),(13,'Chuck Miemiec',1,'Alaskan Fisherman','Male',1,'ChuckMiemiecAvatar2A.png','member','Camiemiec@gmail.com',0,'340 Little River Road','Westfield','MA','01085',1,'978-273-9332',0,4,0,'','1','fish',NULL,'active','2024-09-05 11:28:54',NULL),(14,'Tanya Gorman, Tony Bruehl and Remington',1,'Team Remington','Female',1,'TanyaGormaAvatar10132018.png','member','gormantanya@att.net',0,'1133 Scott Blvd - Unit 14','Decatur','GA','30030',1,' 404-323-6755',0,0,0,'Tanya and Tony let Remington - isn\'t he handsome - pick the teams each week. Remington weighs 6 pounds - but don\'t let that fool you - he is a \"fearless warrior\" and a tough competitor - so the competition better watch out this year.  Team Remington is \"in it to win it\"!!','1','Team Remington',NULL,'active','2022-12-10 00:44:27',NULL),(15,'Brian Burgin',1,'Bradys Balldeflater ','Other',1,'BrianBurgin.png','member','bburgin18@gmail.com',0,'12102 Pine St','Broken Arrow','OK','',1,'630-849-5632',0,6,0,'','1','vceagles',NULL,'inactive','2022-11-30 12:34:58',NULL),(16,'Jessica Joy Burgin',1,'NFL Amateur','Female',1,'jessica.png','member','j.joyhunzelman@yahoo.com',0,'','Broken Arrow','OK','',1,'978-808-9565',0,4,0,'','1','NFL Amateur',NULL,'active','2022-11-30 14:23:44',NULL),(17,'Lisa Hunzelman',1,'Empty Nesters','Female',0,'lisadavid.png','member','l1hunzelman@gmail.com',1,'','Broken Arrow','OK','',0,'978-973-1070',0,4,0,'','1','Empty Nesters',NULL,'active','2025-10-09 16:20:36',NULL),(18,'Ned and Lisa Cutler',1,'Happy Campers','Other',1,'nedlisa.png','member','',0,'275 Slide Brook Rd','Easton','NH','03580',1,'603-823-5050',0,0,1,'','1','Happy Campers',NULL,'inactive','2025-02-24 13:09:22',NULL),(19,'Gary Witham',1,'Beach Bum','Male',1,'gary2.png','member','',0,'','Gloucester','MA','01930',1,'',0,4,0,'','1','beach goer',NULL,'inactive','2025-02-24 13:24:54',NULL),(20,'Leah Jamieson',1,'ANTIC','Female',1,'leah.png','member','',0,'','Townsend','MA','01469',1,'',0,4,1,'','1','ANTIC',NULL,'inactive','2025-02-24 13:16:46',NULL),(21,'Don O Malley ',1,'4Horsemen','Male',1,'donald.png','member','doomalley55@gmail.com',0,'202 Fitchburg Road','Townsend','MA','01469',1,'978-375-3834',0,15,0,'','1','4Horsemen',NULL,'inactive','2025-09-04 19:15:08',NULL),(22,'Sabrina Hunzelman Guzman',1,'Toothfairy','Female',1,'Sabrina Hunzelman10232018.png','member','slhunzelman91@yahoo.com',0,'','Denison','TX','',1,'978-766-2344',0,0,0,'California Girl, from Massachusetts','1','Toothfairy',NULL,'inactive','2025-09-04 20:23:53',NULL),(23,'Judson Jamieson',1,'18 Wheeler','Male',1,'JudsonJamiesonAvatar2.png','member','',0,'4504 Forsythia Way','Ooltewah','TN','37363',1,'',0,4,0,'An old time NFL fan.  Still wating for the L.A. Ram???s Olsen twins to return','1','18 Wheeler',NULL,'inactive','2025-02-24 13:20:48',NULL),(24,'Kris Archuleta',1,'Super Brawler','Male',1,'kris.png','member','krisdarchuleta@gmail.com',0,'30A Belcher Road','Essex','MA','',1,'',0,4,0,'','1','Super Brawler',NULL,'inactive','2025-09-03 16:46:04',NULL),(25,'Bob Craig',1,'Scotsman357','Male',1,'bobby.png','member','scotsman357@gmail.com',0,'17 Wagg Road','Bowdoin','ME','04287',1,'207-504-1075',0,0,0,'','1','Scotsman357',NULL,'active','2023-09-05 16:35:53',NULL),(26,'Jason Shuris',1,'Conan Clones','Male',0,'JasonShuris10132018.png','member','',0,'49 Wilder Rd','Sterling','MA','01564',0,'',0,4,0,'','1','Conan Clones',NULL,'inactive','2025-02-24 13:22:17',NULL),(27,'Marc Check',1,'Improve the Groove','Male',1,'MarcCheck.png','member','',0,'','','SC','44102',1,'',0,0,1,'','1','Improve the Groove',NULL,'inactive','2025-02-24 13:12:32',NULL),(28,'Danny Gomez',0,'Rookie of the Year','Male',0,'dannyg.png','member','',0,'','Similar Valley','CA','93065',0,'',0,0,0,'','0','Rookie of the Year',NULL,'inactive','2025-02-24 13:27:05',NULL),(29,'Steve Paris',1,'Exploding Brain','Male',1,'stevep.png','member','sparisma@gmail.com',0,'','Watertown','MA','',1,'617-926-4127',0,4,0,'I\'ve worked with both Tarry and Tammy (2 companies!) and known them for a   l o n g   time.   \r\n\r\nI am far from a football expert - my father completely gave up on me when I used to ask (only half-facetiously) what inning the game was in or who was in the penalty box. :-)  I used to follow the Red Sox and, especially, the Broooooooons all the time. I used to get (occasional) seats in the Gahden Gods section of the OLD Boston Gahden (I\'m dating myself) - and it was a LOT of fun.  Unfortunately, ticket prices are outrageous these days and I rarely go to Fenway or the Gahden much anymore.  And, yes, it is pronounced \"Gahden\" - and take that all you non-native-to-Bohston types!\r\n\r\nBelieve it or not, I have never BEEN to a game at Gillette Stadium and would only go to one if the weather was between 50 and 80 and dry - or if I were seated in a suite stocked with plenty of hors d\'oeuvres, Bahama Mamas, and rum & cokes. This rules out August, early September, November and December....in other words, probably only 2-3 home games during the entire season.\r\n\r\nMy favorite activities are looking for spare change in the couch cushions after guests have departed after a fun evening of 1) cards - like \"Go Fish!\" - and 2) watching reruns (for the 20th time) of my old (and silent) 8mm home movies of my trip to Alaska in 1981.  I also enjoy dangling my feet in buckets of cold water and inviting all the neighborhood rabbits to eat the grass in my backyard so I don\'t have to mow or hire someone to cut the darn stuff.\r\n\r\nI have a wonderful cat named Bobby, adopted from the MSCPA nearly 15 years ago and is very affectionate to my sister and yours truly. However, he is fiercely protective and will eat other people for his dinner when they visit (that is, after they\'ve played Go Fish!, watched the silent old movies and deposited their change in the couch cushions.)\r\n\r\nIn any case, thanks to Mr. Tarry for creating this site.  It took a lot of persuading, but I finally got into it and I look forward to making my picks each week!','1','B0bby',NULL,'active','2022-11-30 14:24:14',NULL),(30,'Marilyn Brady',1,'Sville 5','Other',0,'SummervilleAvatar.png','member','msbrady@sc.rr.com',0,'1001 Mesa Court','Summerville','SC','29423',0,'843-670-0826',0,0,0,'','1','Sville 5',NULL,'active','2026-10-01 06:54:21',NULL),(31,'Kay Allard',0,'Red Bird','Female',0,'KayAvatar10222018.png','member','',0,'','Manchester by the Sea','MA','01944',0,'',0,4,0,'','0','Red Bird',NULL,'inactive','2025-02-24 13:18:20',NULL),(32,'Kathie DellaPiana',0,'Kathie','Female',0,'default.png','member','',0,'','','MA','',0,'',0,4,0,'','0','kathie',NULL,'inactive','2025-02-24 13:19:54',NULL),(33,'Pat MacKay',1,'Lady Luck','Female',1,'PatMacKayAvatar7.png','member','patriciaemackay@msn.com',0,'18 Ceder St','Hudson','NH','03051',1,'603-801-1117',0,4,0,'','1','Lady Luck',NULL,'active','2017-09-24 16:49:58',NULL),(34,'Kathy Foley',0,'KathyF','Female',0,'default.png','member','',0,'','Hampton','NH','',0,'',0,0,0,'','0','KathyF',NULL,'inactive','2025-02-24 13:19:26',NULL),(35,'Scott Therrien',1,'ScottT','Male',1,'SteveTherrienAvatar2A.png','member','Stottnik@aol.com',0,'339 Primrose Street','Haverhill','MA','01830',1,'978-204-1673',0,4,0,'','1','ScottT',NULL,'inactive','2025-09-25 20:52:19',NULL),(36,'Sandy Therrien',1,'SandyT','Female',1,'SandyTherrienAvatar10132018.png','member','',0,'367 Pine Run Drive','Osprey','FL','34229',1,'941-724-2243',0,4,1,'','1','SandyT',NULL,'inactive','2025-02-24 13:03:19',NULL),(37,'Paula Bishop',1,'Hawk Eye','Female',0,'PaulaBishopAvatar2A.png','member','',1,'','Rowley','MA','01969',0,'978-375-9394',1,4,1,'','0','Hawk Eye',NULL,'inactive','2025-02-24 13:07:19',NULL),(38,'Donna Williamson',1,'DonnaW','? string:Not Selected ?',1,'default.png','memb